-- public.stone_ground_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.stone_ground_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_size int; v_id text;
begin
  if not stone_guarded(p_action) then return null; end if;
  select w.size into v_size from world w where w.id = p_world;
  select runestone_on(v_size, t.x, t.y) into v_id
    from stone_job_tiles(p_world, p_uid, p_action, p_target) with ordinality t(x, y, o)
   where runestone_on(v_size, t.x, t.y) is not null
   order by t.o limit 1;
  if v_id is null then return null; end if;
  return 'Ground of ' || runestone_name(v_id) || ': no digging, building, planting or setting down.';
end $function$
